  effects: store(products), store(tags)
{
  let counts = map(scan(tags), |t| TagCount { tag: t.name, count: 0 })
  for p in scan(products) {
    for t in p.tags {
      for c in counts {
        if c.tag == t {
          c.count = c.count + 1
          break
        }
      }
    }
  }
  return sort_by(counts, |c| c.tag)
}

type TagCount {
  tag: String,
  count: Int,
}
