use std.{Option, Some, None}
use std.{String, trim, str_len, is_email, hash_password, uuid, verify_password}

table users: User key email

type User {
  email: String,
  name: String,
  password_hash: String,
  id: String,
  default_address: Option<Address>,
}

type Signup {
  email: String,
  name: String,
  password: String,
}

type Profile {
  email: String,
  name: String,
}

type UserError =
  | Taken(email: String)
  | BadLogin

type Address {
  street: String,
  city: String,
  postcode: String,
}

api fn signup(input: Signup) -> Result[Profile, UserError]
  route: POST "/users"
  effects: rand, store(users)
  requires: is_email(input.email) && str_len(trim(input.name)) > 0 && str_len(input.password) >= 8
{
  if is_some(get(users, input.email)) {
    return Err(Taken(input.email))
  }
  let user = User {
    email: input.email,
    name: trim(input.name),
    password_hash: hash_password(input.password),
    id: uuid(),
    default_address: None,
  }
  insert(users, user)
  return Ok(profile(user))
}

fn profile(u: User) -> Profile {
  return Profile { email: u.email, name: u.name }
}

api fn login(input: Signup) -> Result[Profile, UserError]
  route: POST "/login"
  effects: store(users)
{
  return match get(users, input.email) {
    Some(u) => match verify_password(input.password, u.password_hash) {
      true => Ok(profile(u)),
      false => Err(BadLogin),
    },
    None => Err(BadLogin),
  }
}

api fn set_default_address(email: String, address: Address) -> Result[Address, UserError]
  route: PUT "/users/{email}/default-address"
  effects: store(users)
  requires: str_len(trim(address.street)) > 0 && str_len(trim(address.city)) > 0 && str_len(address.postcode) >= 3
{
  let user = try get(users, email)
  let updated_user = User {
    email: user.email,
    name: user.name,
    password_hash: user.password_hash,
    id: user.id,
    default_address: Some(address),
  }
  save(users, updated_user)
  return Ok(address)
}

api fn get_default_address(email: String) -> Result[Option[Address], UserError]
  route: GET "/users/{email}/default-address"
  effects: store(users)
{
  let user = try get(users, email)
  return Ok(user.default_address)
}
